"""Admin deletes a synthetic option with inline confirmation; it disappears from receipt choices."""
import asyncio
from playwright.async_api import async_playwright
H='http://127.0.0.1:8010'
async def main():
 async with async_playwright() as pw:
  b=await pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);errors=[]
  for width in [390,1280]:
   c=await b.new_context(viewport={'width':width,'height':844});await c.route('https://**/*',lambda r:r.abort());p=await c.new_page();p.on('pageerror',lambda e:errors.append(str(e)));await p.goto(H+'/login');await p.locator('input[type=text]').first.fill('TESTADMIN');await p.locator('input[type=password]').fill('PruebaSegura123!');await p.get_by_role('button',name='Iniciar Sesión',exact=True).click();await p.wait_for_function('window.SICIPCentral?.user');await p.goto(H+'/admin?seccion=recepcion');await p.get_by_role('heading',name='Catálogo de recepción',exact=True).wait_for();form=p.locator('.admin-personal-card form');category='Prueba de eliminación '+str(width);name='Documento sintético '+str(width);await form.locator('[name=categoria]').fill(category);await form.locator('[name=nombre]').fill(name);await form.get_by_role('button',name='Guardar documento').click();await p.locator('[data-status]').filter(has_text='Documento guardado').wait_for();await p.locator('[data-search]').fill(name);row=p.locator('tbody tr').filter(has_text=name);await row.wait_for();assert await row.count()==1;await row.get_by_role('button',name='Eliminar',exact=True).click();confirm=p.locator('[data-delete-confirm]');await confirm.wait_for();assert name in await confirm.inner_text();assert await p.locator('dialog').count()==0;await confirm.get_by_role('button',name='Conservar documento').click();await confirm.wait_for(state='hidden');assert await row.count()==1
   await row.get_by_role('button',name='Editar',exact=True).click();assert await form.locator('[name=nombre]').input_value()==name;await row.get_by_role('button',name='Eliminar',exact=True).click();await confirm.get_by_role('button',name='Confirmar eliminación').click();await p.locator('[data-status]').filter(has_text='Documento eliminado').wait_for();assert await row.count()==0;assert await form.locator('[name=nombre]').input_value()=='';assert await p.evaluate('document.documentElement.scrollWidth<=innerWidth+1');await p.screenshot(path=f'/tmp/recepcion-eliminar-{width}.png');await p.reload();await p.get_by_role('heading',name='Catálogo de recepción',exact=True).wait_for();await p.locator('[data-search]').fill(name);assert await p.locator('tbody tr').filter(has_text=name).count()==0
   await p.goto(H+'/recepciones');await p.locator('#sicip-recep-selector').wait_for();await p.get_by_text('Registrar manualmente',exact=True).click();await p.wait_for_function("document.querySelector('#sicip-recep-tipo')?.options.length>1");assert category not in await p.locator('#sicip-recep-tipo').inner_text();await c.close();print(f'{width}: cancelar conserva documento; confirmar elimina opción, limpia edición y persiste al recargar y al abrir recepción manual.',flush=True)
  assert not errors,errors;await b.close()
asyncio.run(main())
